#include <windows.h>
#include <stdio.h>
static BOOL armed;
static LRESULT CALLBACK parent_proc(HWND w,UINT m,WPARAM a,LPARAM b)
{
    if(m==WM_CTLCOLOREDIT||m==WM_CTLCOLORSTATIC){
        if(armed){armed=FALSE;fprintf(stderr,"NATIVE_PARENT_DESTROY\n");DestroyWindow((HWND)b);}
        SetBkColor((HDC)a,GetSysColor(COLOR_WINDOW));return (LRESULT)GetSysColorBrush(COLOR_WINDOW);
    }
    return DefWindowProcW(w,m,a,b);
}
int main(void)
{
    HINSTANCE h=GetModuleHandleW(NULL);WNDCLASSW c={.lpfnWndProc=parent_proc,.hInstance=h,.lpszClassName=L"OwnedNativeEditDestroy"};
    if(!RegisterClassW(&c))return 2;
    HWND p=CreateWindowExW(WS_EX_NOACTIVATE,c.lpszClassName,L"",WS_POPUP|WS_VISIBLE,-10000,-10000,300,180,NULL,NULL,h,NULL);
    HWND e=CreateWindowExW(WS_EX_CLIENTEDGE,L"EDIT",L"Retire",WS_CHILD|WS_VISIBLE,0,0,160,48,p,NULL,h,NULL);
    HDC dc=CreateCompatibleDC(NULL);HBITMAP bm=CreateCompatibleBitmap(GetDC(NULL),200,80);HGDIOBJ old=SelectObject(dc,bm);
    armed=TRUE;SendMessageW(e,WM_PRINT,(WPARAM)dc,PRF_NONCLIENT|PRF_CLIENT|PRF_ERASEBKGND);
    fprintf(stderr,"NATIVE_DESTROY_RETURNED\n");SelectObject(dc,old);DeleteObject(bm);DeleteDC(dc);DestroyWindow(p);return 0;
}
